+        'every event; the tracker stays out when the feature is not '
+        'active — TUI / --stream-thinking)', () {
+      final tracker = build();
+      tracker.unrenderedEvent();
+      tracker.renderedOutput();
+      tracker.tick();
+      expect(lines, isEmpty);
+      expect(tracker.armed, isFalse);
