          contentIndex: 0,
          delta: 'plain answer',
          partial: testAssistant(content: [TextContent(text: 'plain')]),
        ),
        DoneEvent(
          reason: StopReason.stop,
          message: testAssistant(content: [TextContent(text: 'plain')]),
