    stream.push(StartEvent(partial: empty));
    stream.push(ThinkingStartEvent(contentIndex: 0, partial: empty));
    stream.push(
      ThinkingDeltaEvent(
        contentIndex: 0,
        delta: 'pondering',
        partial: withThinking,
