            ThinkingContent(thinking: 'pondering'),
            TextContent(text: 'Answer'),
          ],
        );
        stream.push(
          TextDeltaEvent(contentIndex: 1, delta: 'Answer', partial: withText),
        );
        stream.push(DoneEvent(reason: StopReason.stop, message: withText));
        stream.end();
      }),
    );
