    """AC6 (issue #1185): the ⏳ share of a progress stream, in bytes."""

    def test_counts_only_liveness_lines_with_newlines(self):
        stream = (
            "assistant text\n"
            "⏳ [bash] sleep 500 — running 60s\n"
            "✓ bash · 61s\n"
            "⏳ [bash] sleep 500 — running 120s\n"
