  void _evaluate() {
    final since = _since;
    if (since == null) return;
    final remindAfter = _livenessSeconds();
    if (remindAfter <= 0) return;
    final elapsed = _clock().difference(since).inSeconds;
    if (elapsed < remindAfter) return;
    _onRemind(elapsed);
