      now = now.add(const Duration(seconds: 60));
      cli.streamLivenessTickForTest();
    }
    expect('(streaming)'.allMatches(io.out.toString()), hasLength(1));

    fake.release();
    await run;
  });

  test('AC2: a request with NO events still heartbeats via tier-2 only '
