      // otherwise print the honest detach summary before exiting.
      await _waiting.waitForJobsOrSummarize(waitForJobs: waitForJobs);
    } catch (error) {
      io.writeln(
        _keyStatusView.errorLine('$error', _agent.state.model.baseUrl),
      );
      return 1;
    } finally {
