        // image content blocks next to the (redacted) prompt text.
        await _agent.promptMessage(
          UserMessage(
            content: [
              TextContent(text: _redactUserText(prompt)),
              ...images,
            ],
            timestamp: DateTime.now(),
          ),
        );
      }
