void main() {
  late MemoryExecutionEnv env;
  late FakeCliIO io;

  setUp(() {
    env = MemoryExecutionEnv(cwd: '/work');
    io = FakeCliIO();
  });

  tearDown(() => io.close());

  AgentCli buildCli(
    FakeStreamFunction stream, {
    RedactionPipeline? redaction,
  }) => AgentCli(
    config: AgentCliConfig(
      model: testModel,
